# Tests for make_subplots() (R/subplots.R) and row/col placement, compared
# with plotly.py's output in tests/fixtures/plotly-py-subplots.json
# (generated by codegen/fixtures/make_subplots_fixtures.py).
library(plotly.core)

expect_error <- function(expr, pattern) {
  msg <- tryCatch(
    {
      expr
      NULL
    },
    error = function(e) conditionMessage(e)
  )
  if (is.null(msg)) {
    stop(
      "Expected an error matching '",
      pattern,
      "' but none was raised",
      call. = FALSE
    )
  }
  if (!grepl(pattern, msg)) {
    stop("Error message did not match '", pattern, "':\n", msg, call. = FALSE)
  }
  invisible(TRUE)
}
plain <- function(x) {
  if (is.list(x)) {
    x <- unclass(x)
    x[] <- lapply(x, plain)
  }
  x
}
# Round-trip through JSON and sort object keys, to compare with plotly.py
normalise <- function(x) {
  sortr <- function(x) {
    if (is.list(x)) {
      if (!is.null(names(x))) {
        x <- x[order(names(x))]
      }
      x[] <- lapply(x, sortr)
    }
    x
  }
  sortr(jsonlite::fromJSON(
    as.character(plotly.core:::to_JSON(plain(x))),
    simplifyVector = FALSE
  ))
}
expect_same_json <- function(r, py, what) {
  res <- all.equal(normalise(r), normalise(py), tolerance = 1e-12)
  if (!isTRUE(res)) {
    stop(
      what,
      " differs from plotly.py:\n",
      paste(utils::head(res, 5), collapse = "\n"),
      call. = FALSE
    )
  }
}

fixtures <- jsonlite::read_json(file.path(
  "fixtures",
  "plotly-py-subplots.json"
))

# make_subplots() matches plotly.py -------------------------------------------------
cases <- list(
  basic = list(rows = 2, cols = 3),
  titles = list(rows = 2, cols = 2, subplot_titles = c("A", "B", "", "D")),
  shared_x = list(
    rows = 3,
    cols = 2,
    shared_xaxes = TRUE,
    vertical_spacing = 0.05
  ),
  shared_all = list(
    rows = 2,
    cols = 2,
    shared_xaxes = "all",
    shared_yaxes = "all"
  ),
  bottom_left = list(
    rows = 2,
    cols = 2,
    start_cell = "bottom-left",
    row_heights = c(1, 3),
    column_widths = c(0.7, 0.3)
  ),
  specs = list(
    rows = 2,
    cols = 2,
    specs = list(
      list(list(secondary_y = TRUE), list(type = "domain")),
      list(list(colspan = 2), NULL)
    )
  ),
  mixed = list(
    rows = 2,
    cols = 3,
    specs = list(
      list(list(type = "polar"), list(type = "scene"), list(type = "pie")),
      list(list(rowspan = 1), list(type = "ternary"), list(type = "geo"))
    ),
    column_titles = c("c1", "c2", "c3"),
    row_titles = c("r1", "r2"),
    x_title = "X",
    y_title = "Y"
  ),
  rowspan = list(
    rows = 3,
    cols = 2,
    specs = list(
      list(list(rowspan = 2), list()),
      list(NULL, list()),
      list(list(colspan = 2), NULL)
    )
  ),
  insets = list(
    rows = 1,
    cols = 2,
    insets = list(list(cell = c(1, 2), l = 0.5, b = 0.5))
  )
)
stopifnot(setequal(names(cases), names(fixtures$cases)))
for (name in names(cases)) {
  fig <- do.call(make_subplots, cases[[name]])
  py <- fixtures$cases[[name]]
  expect_same_json(fig$layout, py$layout, paste("Layout of case", name))
  if (!identical(attr(fig, "grid_str"), py$grid)) {
    stop("Grid string of case ", name, " differs from plotly.py")
  }
}

# Placing traces, axes updates, annotations and shapes matches plotly.py --------------
fig <- make_subplots(
  rows = 2,
  cols = 2,
  specs = list(
    list(list(secondary_y = TRUE), list(type = "domain")),
    list(list(), list(type = "polar"))
  )
) |>
  add_trace(go_scatter(y = c(1, 2)), row = 1, col = 1) |>
  add_trace(go_scatter(y = c(3, 4)), row = 1, col = 1, secondary_y = TRUE) |>
  add_trace(go_pie(values = c(1, 2)), row = 1, col = 2) |>
  add_trace(go_bar(y = c(5, 6)), row = 2, col = 1) |>
  add_trace(go_scatterpolar(r = c(1, 2), theta = c(0, 90)), row = 2, col = 2) |>
  add_scatter(y = c(7, 8), row = "all", col = 1) |>
  update_xaxes(title_text = "bottom x", row = 2, col = 1) |>
  update_yaxes(
    title_text = "secondary",
    row = 1,
    col = 1,
    secondary_y = TRUE
  ) |>
  update_traces(marker_color = "red", row = 1, col = 1) |>
  add_annotation(text = "note", x = 1, y = 1, row = 2, col = 1) |>
  add_shape(
    type = "line",
    x0 = 0,
    x1 = 1,
    y0 = 0,
    y1 = 1,
    xref = "x domain",
    row = 1,
    col = 1,
    secondary_y = TRUE
  ) |>
  update_annotations(font_size = 20, row = 2, col = 1) |>
  update_polars(radialaxis_range = c(0, 3), row = 2, col = 2)
expect_same_json(fig$data, fixtures$placement$data, "Placement data")
expect_same_json(fig$layout, fixtures$placement$layout, "Placement layout")

# Selection by grid cell --------------------------------------------------------------
stopifnot(
  length(select_traces(fig, row = 1, col = 1)) == 3L,
  length(select_traces(fig, row = 1, col = 1, secondary_y = TRUE)) == 1L,
  length(select_traces(fig, col = 1)) == 5L,
  identical(select_traces(fig, row = 1, col = 2)[[1L]]$type, "pie"),
  identical(names(select_xaxes(fig, row = 2)), "xaxis2"),
  identical(names(select_yaxes(fig, row = 1, col = 1)), c("yaxis", "yaxis2")),
  identical(
    names(select_yaxes(fig, secondary_y = FALSE)),
    c("yaxis", "yaxis3")
  ),
  length(select_annotations(fig, row = 2, col = 1)) == 1L,
  length(select_annotations(fig, row = 1, col = 1)) == 0L,
  identical(select_traces(fig, 2, row = 1, col = 1)[[1L]]$yaxis, "y2") # index into the cell's traces
)

# get_subplot() and print_grid() --------------------------------------------------------
sp <- get_subplot(fig, 1, 1)
stopifnot(
  inherits(sp$xaxis, "go_layout_xaxis"),
  identical(sp$yaxis$anchor, "x")
)
stopifnot(identical(
  get_subplot(fig, 1, 1, secondary_y = TRUE)$yaxis$side,
  "right"
))
stopifnot(identical(names(get_subplot(fig, 1, 2)), c("x", "y"))) # domain subplot
stopifnot(inherits(get_subplot(fig, 2, 2), "go_layout_polar"))
grid_out <- utils::capture.output(print_grid(fig))
stopifnot(grepl("(1,1) x,y,y2", grid_out[[2L]], fixed = TRUE))

# The grid survives every figure operation
fig2 <- fig |>
  update_layout(title = "T") |>
  add_scatter(y = 1) |>
  for_each_trace(identity)
fig2$layout$width <- 500
stopifnot(identical(attr(fig2, "grid_ref"), attr(fig, "grid_ref")))

# exclude_empty_subplots ------------------------------------------------------------------
f3 <- make_subplots(rows = 1, cols = 2) |>
  add_scatter(y = 1:2, row = 1, col = 1) |>
  add_annotation(
    text = "a",
    x = 1,
    y = 1,
    row = 1,
    col = "all",
    exclude_empty_subplots = TRUE
  )
stopifnot(
  length(f3$layout$annotations) == 1L,
  identical(f3$layout$annotations[[1L]]$xref, "x")
)
f4 <- add_trace(
  f3,
  go_scatter(y = 1),
  row = 1,
  col = 2,
  exclude_empty_subplots = TRUE
)
stopifnot(length(f4$data) == 1L)

# Errors ------------------------------------------------------------------------------------
expect_error(make_subplots(rows = 0), "`rows` must be")
expect_error(
  make_subplots(rows = 2, cols = 2, specs = list(list(list()))),
  "`specs` must be a list of 2 rows"
)
expect_error(
  make_subplots(specs = list(list(list(typ = "xy")))),
  "Invalid key in an element of `specs`: typ"
)
expect_error(
  make_subplots(specs = list(list(list(type = "polar", secondary_y = TRUE)))),
  "only supported for subplots of type 'xy'"
)
expect_error(
  make_subplots(specs = list(list(list(type = "bogus")))),
  "Unsupported subplot type: 'bogus'"
)
expect_error(
  make_subplots(rows = 3, vertical_spacing = 0.6),
  "cannot be greater than"
)
expect_error(
  make_subplots(cols = 2, specs = list(list(list(colspan = 3), NULL))),
  "colspan"
)
expect_error(make_subplots(shared_xaxes = "yes"), "`shared_xaxes` must be")
expect_error(
  add_scatter(go_figure(), y = 1, row = 1, col = 1),
  "you must first use make_subplots"
)
expect_error(
  add_scatter(fig, y = 1, row = 1),
  "row and col must be specified together"
)
expect_error(
  add_trace(fig, go_pie(values = 1), row = 2, col = 1),
  "Trace type 'pie' is not compatible with subplot type 'xy'"
)
expect_error(
  add_trace(fig, go_scatter(y = 1), row = 2, col = 1, secondary_y = TRUE),
  "secondary_y spec property"
)
expect_error(
  add_trace(fig, go_scatter(y = 1), row = 3, col = 1),
  "out of range"
)
expect_error(
  add_annotation(fig, text = "x", row = 1, col = 2),
  "subplot is of type domain"
)
